//! The QR code of the study's repository, drawn as SVG modules. Version 4,
//! error correction M, byte mode; generated by a small standard encoder and
//! decoded back to the URL with the macOS QR detector before it went in.

use fframes::Svgr;

pub const URL: &str = "https://github.com/ediestel/llm_modulation_three_pairs";

/// One row per line, `1` a dark module; 33 × 33.
const MODULES: [&str; 33] = [
    "111111101010110010111001001111111",
    "100000101110110000001001101000001",
    "101110100000000000011010101011101",
    "101110101100001011001010101011101",
    "101110100101011000110010101011101",
    "100000100000111000011110001000001",
    "111111101010101010101010101111111",
    "000000001100001001101001100000000",
    "101101110001001011100110101001011",
    "011111001101000010111101001101101",
    "011000101100001010000101011111011",
    "010011000101011100111010010101000",
    "110011110111000000100011010011011",
    "001110010111010011010100100100110",
    "100001100110011110111100101111100",
    "110101011011100010000101011101100",
    "001010111000011100101110011011100",
    "000001001111001111101011111011011",
    "100101110011011101001110101110110",
    "110011011010010010010011111010010",
    "111010111011101100100100100001101",
    "101100000001001100111100001001101",
    "000010100000111010001101011001011",
    "011000010111111010110001101101011",
    "100100101101001101000011111111010",
    "000000001100101111111000100011011",
    "111111101010010000011001101010000",
    "100000101011000110001111100011110",
    "101110100001010001010011111110110",
    "101110101011110000101101000101001",
    "101110101010011000001010001101100",
    "100000100101111111010011110110001",
    "111111101111010111100101001010100",
];

/// Quiet zone, in modules, on every side.
const QUIET: f32 = 4.0;

/// The code with its white quiet zone, top-left at (x, y), `m` pixels per
/// module. Dark runs of a row are one rectangle each.
pub fn qr(x: f32, y: f32, m: f32) -> Svgr<'static> {
    let n = MODULES.len() as f32;
    let side = (n + 2.0 * QUIET) * m;
    let mut d = String::new();
    for (r, row) in MODULES.iter().enumerate() {
        let bytes = row.as_bytes();
        let mut c = 0;
        while c < bytes.len() {
            if bytes[c] == b'1' {
                let start = c;
                while c < bytes.len() && bytes[c] == b'1' {
                    c += 1;
                }
                let px = x + (QUIET + start as f32) * m;
                let py = y + (QUIET + r as f32) * m;
                d.push_str(&format!("M{px:.2} {py:.2}h{:.2}v{m:.2}h{:.2}z", (c - start) as f32 * m, -((c - start) as f32) * m));
            } else {
                c += 1;
            }
        }
    }
    fframes::svgr!(
        <g>
            <rect x={x} y={y} width={side} height={side} fill="#FFFFFF" />
            <path d={d} fill="#000000" shape-rendering="crispEdges" />
        </g>
    )
}
